using DriveOS.Modules.Workforce.Domain.ProfessionalRestrictions;using DriveOS.SharedKernel.Identifiers;using Microsoft.EntityFrameworkCore;using Microsoft.EntityFrameworkCore.Metadata.Builders;
namespace DriveOS.Modules.Workforce.Infrastructure.Persistence.Configurations;
internal sealed class ProfessionalRestrictionConfiguration:IEntityTypeConfiguration<ProfessionalRestriction>{public void Configure(EntityTypeBuilder<ProfessionalRestriction> b){b.ToTable("professional_restrictions");b.HasKey(x=>x.Id);b.Property(x=>x.Id).HasConversion(x=>x.Value,x=>new ProfessionalRestrictionId(x)).ValueGeneratedNever();b.Property(x=>x.OrganizationId).HasConversion(x=>x.Value,x=>new OrganizationId(x));b.Property(x=>x.EmployeeId).HasConversion(x=>x.Value,x=>new EmployeeId(x));b.Property(x=>x.BranchId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new BranchId(x.Value):null);b.Property(x=>x.Activity).HasConversion<int>();b.Property(x=>x.Source).HasConversion<int>();b.Property(x=>x.Status).HasConversion<int>();b.Property(x=>x.Reason).HasMaxLength(1000).IsRequired();b.Property(x=>x.CountryCode).HasMaxLength(8);b.Property(x=>x.LicenseCategoryCode).HasMaxLength(32);b.Property(x=>x.LiftReason).HasMaxLength(1000);b.Property(x=>x.CancellationReason).HasMaxLength(1000);b.Property(x=>x.ActivatedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.LiftedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.CancelledByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.CreatedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.Property(x=>x.LastModifiedByUserId).HasConversion(x=>x.HasValue?x.Value.Value:(Guid?)null,x=>x.HasValue?new UserId(x.Value):null);b.HasIndex(x=>new{x.OrganizationId,x.EmployeeId,x.Status});b.HasIndex(x=>new{x.OrganizationId,x.Activity,x.Status,x.StartDate,x.EndDate});b.HasIndex(x=>new{x.OrganizationId,x.EmployeeId,x.CountryCode,x.LicenseCategoryCode});}}
